import React, { useState, useEffect } from 'react'
import { useParams } from 'react-router-dom'
import api from '../../../services/api'

export default function ChildProfile() {
  const { id } = useParams()
  const [activeTab, setActiveTab] = useState('Overview')
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [showCCTV, setShowCCTV] = useState(false)

  useEffect(() => {
    const fetchChildProfile = async () => {
      try {
        const res = await api.get(`/dashboard/parent/child/${id || '1'}`)
        if (res.data && res.data.ok) {
          setData(res.data.data)
        }
      } catch (error) {
        console.error('Failed to fetch child profile:', error)
      } finally {
        setLoading(false)
      }
    }
    fetchChildProfile()
  }, [id])

  if (loading) {
    return <div className="text-slate-800 text-center py-20">Loading child profile...</div>
  }

  if (!data) {
    return <div className="text-red-400 text-center py-20">Failed to load data. Please ensure backend is running.</div>
  }

  const { profile, overviewStats, recentActivities, liveUpdates, weeklyProgress, schedule, health } = data

  const tabs = ['Overview', 'Weekly Progress', 'Schedule', 'Health & Growth']

  const renderOverview = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-fuchsia-600 rounded-2xl p-5 flex flex-col justify-between">
          <div className="flex items-center gap-2 mb-2 text-slate-800/80">
            <span>🍽️</span>
            <span className="text-2xl font-bold text-slate-800">{overviewStats.mealsCompleted}</span>
          </div>
          <p className="text-sm font-semibold text-slate-800">Meals Completed</p>
        </div>
        <div className="bg-fuchsia-500 rounded-2xl p-5 flex flex-col justify-between">
          <div className="flex items-center gap-2 mb-2 text-slate-800/80">
            <span>😴</span>
            <span className="text-2xl font-bold text-slate-800">{overviewStats.napTimeToday}</span>
          </div>
          <p className="text-sm font-semibold text-slate-800">Nap Time Today</p>
        </div>
        <div className="bg-green-500 rounded-2xl p-5 flex flex-col justify-between">
          <div className="flex items-center gap-2 mb-2 text-slate-800/80">
            <span>📈</span>
            <span className="text-2xl font-bold text-slate-800">{overviewStats.activitiesDone}</span>
          </div>
          <p className="text-sm font-semibold text-slate-800">Activities Done</p>
        </div>
        <div className="bg-orange-500 rounded-2xl p-5 flex flex-col justify-between">
          <div className="flex items-center gap-2 mb-2 text-slate-800/80">
            <span>📚</span>
            <span className="text-2xl font-bold text-slate-800">{overviewStats.learningSessions}</span>
          </div>
          <p className="text-sm font-semibold text-slate-800">Learning Sessions</p>
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold text-slate-800">Recent Activities</h3>
          <a href="#" className="text-xs text-slate-500 hover:text-slate-800">View All</a>
        </div>
        <div className="space-y-3">
          {recentActivities.map((activity, idx) => (
            <div key={idx} className="flex justify-between items-center p-3 rounded-xl border border-slate-200 hover:bg-white/5">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 bg-${activity.color}-500/20 text-${activity.color}-400 rounded-lg flex items-center justify-center`}>{activity.icon}</div>
                <div>
                  <p className="text-sm font-semibold text-slate-800">{activity.title}</p>
                  <p className="text-xs text-slate-500">{activity.time}</p>
                </div>
              </div>
              <span className="text-green-500">✓</span>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <div className="flex items-center gap-2 mb-4">
          <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
          <h3 className="font-bold text-slate-800">Live Daycare Updates</h3>
        </div>
        {liveUpdates.map((update, idx) => (
          <div key={idx} className={`p-4 rounded-xl border border-slate-200 bg-${update.color}-500/10 mb-3 last:mb-0`}>
            <div className="flex items-start gap-3">
              <div className={`w-10 h-10 bg-${update.color}-500 rounded-full flex items-center justify-center text-slate-800 shrink-0`}>{update.icon}</div>
              <div>
                <p className={`text-sm font-semibold text-${update.color}-400`}>{update.title}</p>
                <p className="text-sm text-slate-600 mt-1">{update.description}</p>
                <p className="text-xs text-slate-500 mt-2">{update.time}</p>
              </div>
            </div>
          </div>
        ))}
        <button 
          onClick={() => setShowCCTV(true)}
          className="w-full mt-4 py-3 bg-fuchsia-600 hover:bg-fuchsia-500 text-white font-bold rounded-xl text-center transition"
        >
          View Live CCTV Feed
        </button>
      </div>
    </div>
  )

  const renderWeeklyProgress = () => (
    <div className="space-y-6">
      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <h3 className="font-bold text-slate-800 mb-6">Weekly Activity Overview</h3>
        {/* CSS Chart Simulation */}
        <div className="relative h-48 w-full border-b border-l border-slate-200 pb-6 pl-4 flex items-end justify-between">
          <div className="absolute top-0 left-0 w-full h-full flex flex-col justify-between pointer-events-none pb-6 pl-4">
            <div className="w-full border-t border-slate-200 opacity-50"></div>
            <div className="w-full border-t border-slate-200 opacity-50"></div>
            <div className="w-full border-t border-slate-200 opacity-50"></div>
          </div>
          
          {['Mon', 'Tue', 'Wed', 'Thu', 'Fri'].map((day, i) => (
            <div key={day} className="flex flex-col items-center flex-1 z-10">
              <div className="relative w-full h-32 flex justify-center items-center">
                <div className="w-2 h-2 rounded-full bg-green-400 absolute" style={{ bottom: `${40 + (i % 2 === 0 ? 20 : 0)}%` }}></div>
                <div className="w-2 h-2 rounded-full bg-blue-400 absolute" style={{ bottom: `${60 + (i % 3 === 0 ? -10 : 10)}%` }}></div>
                <div className="w-2 h-2 rounded-full bg-fuchsia-400 absolute" style={{ bottom: `${30 + (i * 10)}%` }}></div>
              </div>
              <span className="text-xs text-slate-500 mt-2">{day}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <h3 className="font-bold text-slate-800 mb-6">Learning Progress</h3>
        <div className="space-y-5">
          {weeklyProgress.learningData.map(item => (
            <div key={item.label}>
              <div className="flex justify-between text-xs mb-2">
                <span className="text-slate-600 font-semibold">{item.label}</span>
                <span className="text-slate-500">{item.percent}%</span>
              </div>
              <div className="w-full bg-slate-200 rounded-full h-2 overflow-hidden">
                <div className="bg-fuchsia-500 h-2 rounded-full" style={{ width: `${item.percent}%` }}></div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4">
        <div className="bg-white border border-slate-200 rounded-2xl p-4 flex flex-col gap-2">
          <div className="w-8 h-8 bg-orange-500/20 text-orange-400 rounded flex items-center justify-center">🎓</div>
          <span className="text-2xl font-bold text-slate-800">{weeklyProgress.stats.totalActivities}</span>
          <span className="text-xs text-slate-500">Total Activities</span>
        </div>
        <div className="bg-white border border-slate-200 rounded-2xl p-4 flex flex-col gap-2">
          <div className="w-8 h-8 bg-blue-500/20 text-blue-400 rounded flex items-center justify-center">⏱️</div>
          <span className="text-2xl font-bold text-slate-800">{weeklyProgress.stats.learningHours}</span>
          <span className="text-xs text-slate-500">Learning Hours</span>
        </div>
        <div className="bg-white border border-slate-200 rounded-2xl p-4 flex flex-col gap-2">
          <div className="w-8 h-8 bg-green-500/20 text-green-400 rounded flex items-center justify-center">😴</div>
          <span className="text-2xl font-bold text-slate-800">{weeklyProgress.stats.avgSleep}</span>
          <span className="text-xs text-slate-500">Avg Sleep</span>
        </div>
      </div>
    </div>
  )

  const renderSchedule = () => (
    <div className="space-y-6">
      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <h3 className="font-bold text-slate-800 mb-4">Upcoming This Week</h3>
        <div className="space-y-3">
          {schedule.upcoming.map((item, idx) => (
            <div key={idx} className="flex justify-between items-center p-3 rounded-xl border border-slate-200 hover:bg-white/5">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 ${item.bg} ${item.color} rounded-lg flex items-center justify-center shrink-0`}>
                  {item.icon}
                </div>
                <div>
                  <p className="text-sm font-semibold text-slate-800">{item.label}</p>
                  <p className="text-xs text-slate-500">{item.location}</p>
                </div>
              </div>
              <div className="text-right">
                <p className="text-sm font-semibold text-slate-600">{item.date}</p>
                <p className="text-xs text-slate-500">{item.time}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <h3 className="font-bold text-slate-800 mb-4">Daily Routine</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {schedule.routine.map((routine, idx) => (
            <div key={idx} className="flex items-center gap-3 p-3 rounded-xl border border-slate-200 bg-white/5">
              <div className="text-xl">{routine.icon}</div>
              <div>
                <p className="text-sm font-semibold text-slate-800">{routine.label}</p>
                <p className="text-xs text-slate-500">{routine.time}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )

  const renderHealth = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-green-600 rounded-2xl p-5 flex flex-col justify-between">
          <div className="flex items-center gap-2 mb-2 text-slate-800/80">
            <span>🛡️</span>
            <span className="text-lg font-bold text-slate-800">Vaccinations</span>
          </div>
          <div>
            <p className="text-sm font-semibold text-slate-800">{health.stats.vaccinations}</p>
            <p className="text-xs text-slate-800/80">{health.stats.nextVaccination}</p>
          </div>
        </div>
        <div className="bg-blue-600 rounded-2xl p-5 flex flex-col justify-between">
          <div className="flex items-center gap-2 mb-2 text-slate-800/80">
            <span>📏</span>
            <span className="text-lg font-bold text-slate-800">Height</span>
          </div>
          <div>
            <p className="text-2xl font-bold text-slate-800">{health.stats.height}</p>
            <p className="text-xs text-slate-800/80">{health.stats.heightPercentile}</p>
          </div>
        </div>
        <div className="bg-purple-600 rounded-2xl p-5 flex flex-col justify-between">
          <div className="flex items-center gap-2 mb-2 text-slate-800/80">
            <span>⚖️</span>
            <span className="text-lg font-bold text-slate-800">Weight</span>
          </div>
          <div>
            <p className="text-2xl font-bold text-slate-800">{health.stats.weight}</p>
            <p className="text-xs text-slate-800/80">{health.stats.weightPercentile}</p>
          </div>
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <h3 className="font-bold text-slate-800 mb-6">Growth Tracking</h3>
        <div className="relative h-48 w-full border-b border-l border-slate-200 pb-6 pl-4 flex items-end justify-between">
          <div className="absolute top-0 left-0 w-full h-full flex flex-col justify-between pointer-events-none pb-6 pl-4">
            <div className="w-full border-t border-slate-200 opacity-50"></div>
            <div className="w-full border-t border-slate-200 opacity-50"></div>
            <div className="w-full border-t border-slate-200 opacity-50"></div>
          </div>
          
          {['Oct', 'Nov', 'Dec', 'Jan', 'Feb'].map((month, i) => (
            <div key={month} className="flex flex-col items-center flex-1 z-10 h-full justify-end">
              <div className="flex items-end gap-1 w-full justify-center h-full">
                <div className="w-3 bg-fuchsia-500 rounded-t-sm" style={{ height: `${20 + (i * 5)}%` }}></div>
                <div className="w-6 bg-blue-500 rounded-t-sm" style={{ height: `${60 + (i * 6)}%` }}></div>
              </div>
              <span className="text-xs text-slate-500 mt-2">{month}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <h3 className="font-bold text-slate-800 mb-4">Upcoming Health Events</h3>
        <div className="space-y-3">
          {health.upcomingEvents.map((event, idx) => (
            <div key={idx} className="flex justify-between items-center p-4 rounded-xl border border-slate-200 hover:bg-white/5">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-green-500/20 text-green-400 rounded-lg flex items-center justify-center shrink-0">
                  {event.icon}
                </div>
                <div>
                  <p className="text-sm font-semibold text-slate-800">{event.label}</p>
                  <p className="text-xs text-slate-500">{event.date}</p>
                </div>
              </div>
              <span className="text-green-500">↓</span>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-3xl p-5">
        <h3 className="font-bold text-slate-800 mb-4">Medical Notes</h3>
        <div className="space-y-3">
          {health.notes.map((note, idx) => (
            <div key={idx} className="p-4 rounded-xl border border-slate-200 bg-white/5">
              <div className="flex items-center gap-2 mb-1">
                <span className={`text-${note.color}-500`}>{note.icon}</span>
                <p className="text-sm font-semibold text-slate-800">{note.type}</p>
              </div>
              <p className="text-xs text-slate-500 ml-6">{note.text}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  )

  return (
    <div className="space-y-6 max-w-4xl mx-auto pb-10">
      <div className="mb-2">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-800">Child Profile</h1>
        <p className="text-sm text-slate-500">Monitor your child's growth, activities, and development</p>
      </div>

      {/* Profile Header */}
      <div className="bg-white border border-slate-200 rounded-3xl p-6">
        <div className="flex items-center gap-4 mb-6">
          <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center text-3xl border-2 border-fuchsia-500">
            👶
          </div>
          <div>
            <div className="flex items-center gap-3">
              <h2 className="text-xl font-bold text-slate-800">{profile.name} <span className="text-sm font-normal text-slate-500 ml-2">{profile.age}</span></h2>
              <span className="px-2 py-0.5 bg-blue-600 text-slate-800 text-xs font-bold rounded">{profile.level}</span>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex items-start gap-3 p-4 rounded-xl border border-slate-200 bg-white/5">
            <div className="w-8 h-8 rounded-lg bg-blue-500/20 text-blue-400 flex items-center justify-center shrink-0">🏫</div>
            <div>
              <p className="text-sm font-semibold text-slate-800">Current Daycare</p>
              <p className="text-xs text-slate-500 mt-1">{profile.currentDaycare}</p>
            </div>
          </div>
          <div className="flex items-start gap-3 p-4 rounded-xl border border-slate-200 bg-white/5">
            <div className="w-8 h-8 rounded-lg bg-green-500/20 text-green-400 flex items-center justify-center shrink-0">💉</div>
            <div>
              <p className="text-sm font-semibold text-slate-800">Health Status</p>
              <p className="text-xs text-slate-500 mt-1">{profile.healthStatus}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="flex gap-2 border-b border-slate-200 overflow-x-auto pb-px">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-3 text-sm font-semibold whitespace-nowrap border-b-2 transition ${
              activeTab === tab
                ? 'border-fuchsia-500 text-fuchsia-400 bg-fuchsia-500/10 rounded-t-lg'
                : 'border-transparent text-slate-500 hover:text-slate-800 hover:bg-white/5 rounded-t-lg'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="mt-6">
        {activeTab === 'Overview' && renderOverview()}
        {activeTab === 'Weekly Progress' && renderWeeklyProgress()}
        {activeTab === 'Schedule' && renderSchedule()}
        {activeTab === 'Health & Growth' && renderHealth()}
      </div>

      {/* CCTV Modal */}
      {showCCTV && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
          <div className="bg-white border border-slate-200 p-6 rounded-3xl w-full max-w-2xl text-center">
            <div className="flex justify-between items-center mb-4">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-red-500 animate-pulse"></div>
                <h2 className="text-xl font-bold text-slate-800">Live CCTV Feed</h2>
              </div>
              <button onClick={() => setShowCCTV(false)} className="text-slate-500 hover:text-slate-800">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            
            <div className="w-full aspect-video bg-black rounded-xl overflow-hidden relative border border-slate-200">
              <div className="absolute top-4 left-4 bg-black/50 px-2 py-1 rounded text-xs text-slate-800 font-mono z-10 flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></span>
                CAM-01 • PLAYROOM
              </div>
              <div className="absolute bottom-4 right-4 bg-black/50 px-2 py-1 rounded text-xs text-slate-800 font-mono z-10">
                {new Date().toLocaleTimeString()}
              </div>
              {/* Simulated camera noise/feed placeholder */}
              <div className="w-full h-full bg-slate-50 flex items-center justify-center text-slate-500 relative overflow-hidden">
                <div className="absolute inset-0 opacity-20 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjZmZmIiAvPgo8cmVjdCB3aWR0aD0iMSIgaGVpZ2h0PSIxIiBmaWxsPSIjMDAwIiAvPgo8L3N2Zz4=')]"></div>
                <p>Live Video Stream Playing...</p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}



